import hashlib
import hmac
import json
import os
import time
import secrets
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import threading

SECRET_KEY = secrets.token_bytes(32)
SESSION_STORE = {}
SESSION_LOCK = threading.Lock()

# --- Password hashing (salted, computationally expensive KDF) ---

PBKDF2_ITERATIONS = 200_000

def hash_password(password, salt=None):
    if salt is None:
        salt = secrets.token_bytes(16)
    dk = hashlib.pbkdf2_hmac("sha256", password.encode(), salt, PBKDF2_ITERATIONS)
    return salt.hex() + "$" + dk.hex()

def verify_password(password, stored):
    try:
        salt_hex, _ = stored.split("$", 1)
        salt = bytes.fromhex(salt_hex)
    except (ValueError, AttributeError):
        return False
    candidate = hash_password(password, salt)
    return hmac.compare_digest(candidate, stored)

# --- Authentication & Authorization ---

def create_token(user_id, role):
    payload = json.dumps({"sub": user_id, "role": role, "iat": int(time.time()), "exp": int(time.time()) + 3600})
    sig = hmac.new(SECRET_KEY, payload.encode(), hashlib.sha256).hexdigest()
    return payload.encode().hex() + "." + sig

def verify_token(token):
    try:
        parts = token.split(".")
        if len(parts) != 2:
            return None
        payload_hex, sig = parts
        payload_bytes = bytes.fromhex(payload_hex)
        expected_sig = hmac.new(SECRET_KEY, payload_bytes, hashlib.sha256).hexdigest()
        if not hmac.compare_digest(sig, expected_sig):
            return None
        payload = json.loads(payload_bytes)
        if payload.get("exp", 0) < time.time():
            return None
        return payload
    except (ValueError, json.JSONDecodeError):
        return None

ALLOWED_ROLES = frozenset(["user", "moderator", "admin"])

def require_role(role_list):
    """Decorator factory that restricts access to users with specified roles.
    Creates an immutable copy of the role set for each endpoint."""
    permitted = frozenset(role_list)
    def decorator(handler_func):
        def wrapper(self, user_info, *args, **kwargs):
            user_role = user_info.get("role", "")
            if user_role not in permitted:
                self.send_error_response(403, "Forbidden")
                return
            return handler_func(self, user_info, *args, **kwargs)
        wrapper._allowed_roles = permitted
        return wrapper
    return decorator

# --- Data Store ---

class DocumentStore:
    def __init__(self):
        self._docs = {}
        self._lock = threading.Lock()

    def create(self, doc_id, content, owner):
        with self._lock:
            self._docs[doc_id] = {"content": content, "owner": owner, "created": time.time()}
            return True

    def get(self, doc_id):
        with self._lock:
            return self._docs.get(doc_id, {}).copy()

    def delete(self, doc_id, requester):
        with self._lock:
            doc = self._docs.get(doc_id)
            if doc and doc["owner"] == requester:
                del self._docs[doc_id]
                return True
            return False

    def list_all(self):
        with self._lock:
            return [{"id": k, "owner": v["owner"]} for k, v in self._docs.items()]

store = DocumentStore()

# --- Request Handler ---

class APIHandler(BaseHTTPRequestHandler):

    def send_json(self, code, data):
        body = json.dumps(data).encode()
        self.send_response(code)
        self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_error_response(self, code, message):
        self.send_json(code, {"error": message})

    def authenticate(self):
        auth = self.headers.get("Authorization", "")
        if not auth.startswith("Bearer "):
            return None
        token = auth[7:]
        return verify_token(token)

    def do_GET(self):
        parsed = urlparse(self.path)
        path = parsed.path
        params = parse_qs(parsed.query)

        user = self.authenticate()
        if not user:
            self.send_error_response(401, "Unauthorized")
            return

        if path == "/api/documents":
            self.handle_list_documents(user)
        elif path == "/api/document":
            doc_id = params.get("id", [None])[0]
            if doc_id:
                self.handle_get_document(user, doc_id)
            else:
                self.send_error_response(400, "Missing id")
        elif path == "/api/admin/users":
            self.handle_admin_list_users(user)
        elif path == "/api/admin/audit":
            self.handle_admin_audit(user)
        else:
            self.send_error_response(404, "Not found")

    def do_POST(self):
        parsed = urlparse(self.path)
        path = parsed.path

        if path == "/api/login":
            self.handle_login()
            return

        user = self.authenticate()
        if not user:
            self.send_error_response(401, "Unauthorized")
            return

        if path == "/api/document":
            self.handle_create_document(user)
        elif path == "/api/admin/promote":
            self.handle_admin_promote(user)
        else:
            self.send_error_response(404, "Not found")

    def do_DELETE(self):
        parsed = urlparse(self.path)
        params = parse_qs(parsed.query)

        user = self.authenticate()
        if not user:
            self.send_error_response(401, "Unauthorized")
            return

        if parsed.path == "/api/document":
            doc_id = params.get("id", [None])[0]
            if doc_id:
                self.handle_delete_document(user, doc_id)
            else:
                self.send_error_response(400, "Missing id")
        else:
            self.send_error_response(404, "Not found")

    # --- Handlers with role-based access control ---

    @require_role(["user", "moderator", "admin"])
    def handle_list_documents(self, user):
        docs = store.list_all()
        self.send_json(200, {"documents": docs})

    @require_role(["user", "moderator", "admin"])
    def handle_get_document(self, user, doc_id):
        doc = store.get(doc_id)
        if not doc:
            self.send_error_response(404, "Document not found")
            return
        self.send_json(200, {"document": doc})

    @require_role(["user", "moderator", "admin"])
    def handle_create_document(self, user):
        try:
            length = int(self.headers.get("Content-Length", 0))
            if length > 65536 or length <= 0:
                self.send_error_response(400, "Invalid content length")
                return
            body = json.loads(self.rfile.read(length))
            content = body.get("content", "")
            if not isinstance(content, str) or len(content) > 10000:
                self.send_error_response(400, "Invalid content")
                return
            doc_id = secrets.token_hex(8)
            store.create(doc_id, content, user["sub"])
            self.send_json(201, {"id": doc_id})
        except (ValueError, json.JSONDecodeError):
            self.send_error_response(400, "Bad request")

    @require_role(["user", "moderator", "admin"])
    def handle_delete_document(self, user, doc_id):
        if store.delete(doc_id, user["sub"]):
            self.send_json(200, {"deleted": True})
        else:
            self.send_error_response(403, "Not owner or not found")

    @require_role(["moderator", "admin"])
    def handle_admin_list_users(self, user):
        # In production, this would query a user database
        self.send_json(200, {"users": ["alice", "bob", "charlie"]})

    @require_role(["admin"])
    def handle_admin_audit(self, user):
        # Return audit log
        self.send_json(200, {"audit": "System audit log entries..."})

    @require_role(["admin"])
    def handle_admin_promote(self, user):
        try:
            length = int(self.headers.get("Content-Length", 0))
            if length > 4096 or length <= 0:
                self.send_error_response(400, "Invalid content length")
                return
            body = json.loads(self.rfile.read(length))
            target_user = body.get("user", "")
            new_role = body.get("role", "")
            if not isinstance(target_user, str) or not isinstance(new_role, str):
                self.send_error_response(400, "Invalid input")
                return
            if new_role not in ALLOWED_ROLES:
                self.send_error_response(400, "Invalid role")
                return
            # In production: update user's role in database
            self.send_json(200, {"promoted": target_user, "role": new_role})
        except (ValueError, json.JSONDecodeError):
            self.send_error_response(400, "Bad request")

    # --- Login ---

    USERS = {
        "alice": {"password_hash": hash_password("alice_secret_2024"), "role": "admin"},
        "bob": {"password_hash": hash_password("bob_password_99"), "role": "moderator"},
        "charlie": {"password_hash": hash_password("charlie_pass"), "role": "user"},
    }

    def handle_login(self):
        try:
            length = int(self.headers.get("Content-Length", 0))
            if length > 4096 or length <= 0:
                self.send_error_response(400, "Invalid content length")
                return
            body = json.loads(self.rfile.read(length))
            username = body.get("username", "")
            password = body.get("password", "")
            if not isinstance(username, str) or not isinstance(password, str):
                self.send_error_response(400, "Invalid input")
                return
            user_record = self.USERS.get(username)
            if not user_record:
                # Perform a dummy verification to reduce user-enumeration timing leaks
                verify_password(password, hash_password("dummy"))
                self.send_error_response(401, "Invalid credentials")
                return
            if not verify_password(password, user_record["password_hash"]):
                self.send_error_response(401, "Invalid credentials")
                return
            token = create_token(username, user_record["role"])
            self.send_json(200, {"token": token})
        except (ValueError, json.JSONDecodeError):
            self.send_error_response(400, "Bad request")

    def log_message(self, format, *args):
        pass  # Suppress default logging

if __name__ == "__main__":
    server = HTTPServer(("127.0.0.1", 8080), APIHandler)
    server.serve_forever()
